CREATE TABLE IF NOT EXISTS orders (reference TEXT PRIMARY KEY, uid TEXT NOT NULL, amount_cents INTEGER NOT NULL, status TEXT NOT NULL, tx_id TEXT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payment_events (tx_id TEXT NOT NULL, status TEXT NOT NULL, reference TEXT, created_at INTEGER NOT NULL, UNIQUE(tx_id,status));
CREATE TABLE IF NOT EXISTS entitlements (uid TEXT PRIMARY KEY, until INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS consents (uid TEXT NOT NULL, kind TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS progress (uid TEXT PRIMARY KEY, data TEXT NOT NULL, updated_at INTEGER NOT NULL);
